function Course(name, hours) {
  if (!(this instanceof Course)) {
    return new Course(name, hours);
  }

  this.name = name;
  this.hours = hours;
}

Course.prototype.describe = function () {
  return this.name + ' · ' + this.hours + '시간';
};

Course.prototype.isLong = function () {
  return this.hours >= 10;
};

Course.prototype.addHours = function (n) {
  this.hours += n;
  return this;
};

// 이 함수는 그대로 두세요
function report(name, hours, add) {
  const withNew = new Course(name, hours);
  const withoutNew = Course(name, hours);
  return withNew.addHours(add).describe()
    + ' / 긴 강의인가: ' + withNew.isLong()
    + ' / new 없이도: ' + (withoutNew instanceof Course ? withoutNew.describe() : '실패')
    + ' / 나눠 쓰는가: ' + (withNew.describe === withoutNew.describe);
}
